    (composeConcordant Q R).disc = Q.disc

theorem eval_modEq {Q : BinaryQuadraticForm} {m x x' y y' : ℤ}
    (hx : x ≡ x' [ZMOD m]) (hy : y ≡ y' [ZMOD m]) :
    Q.eval x y ≡ Q.eval x' y' [ZMOD m]

theorem exists_coprime_eval_of_isPrimitive {Q : BinaryQuadraticForm}
    (hQ : Q.IsPrimitive) {M : ℤ} (hM : M ≠ 0) :
    ∃ x y : ℤ, Int.gcd x y = 1 ∧ Int.gcd (Q.eval x y) M = 1

theorem gcd_eq_one_of_forall_prime_not_dvd {n M : ℤ}
    (h : ∀ p : ℕ, p.Prime → (p : ℤ) ∣ M → ¬ (p : ℤ) ∣ n) :
    Int.gcd n M = 1

theorem finrank_ratAlgebra_eq_finrank_quadraticAlgebra (d : ℚ)
    [Fact (¬ IsSquare d)] :
    @Module.finrank ℚ (Qsqrtd d) _ _
      (@Algebra.toModule ℚ (Qsqrtd d) _ _ DivisionRing.toRatAlgebra) =
    @Module.finrank ℚ (Qsqrtd d) _ _
      (@Algebra.toModule ℚ (Qsqrtd d) _ _ QuadraticAlgebra.instAlgebra)

theorem finrank_ratAlgebra_eq_two (d : ℚ) [Fact (¬ IsSquare d)] :
    @Module.finrank ℚ (Qsqrtd d) _ _
      (@Algebra.toModule ℚ (Qsqrtd d) _ _ DivisionRing.toRatAlgebra) = 2

theorem isCoprime_param_num_den_of_not_three_dvd {m n : ℤ}
    (hmn : IsCoprime m n) (h3m : ¬ (3 : ℤ) ∣ m) :
    IsCoprime (2 * m * n - 3 * n ^ 2) (m ^ 2 - 3 * n ^ 2)

theorem isCoprime_three_dvd_param_num_den {r n : ℤ}
    (hrn : IsCoprime r n) (h3n : ¬ (3 : ℤ) ∣ n) :
